1	package server
2	
3	import (
4		"fmt"
5		"net/http"
6		"net/http/httptest"
7		"path/filepath"
8		"strings"
9		"testing"
10	
11		"github.com/alicegogogogogo/local-first-sync-service/internal/app"
12	)
13	
14	// getAttachmentContent issues the whole-content read and returns the raw
15	// recorder so tests can assert status, content type and body bytes.
16	func getAttachmentContent(t *testing.T, h http.Handler, deviceID, attachmentID string) *httptest.ResponseRecorder {
17		t.Helper()
18		r := httptest.NewRequest(http.MethodGet,
19			"/v1/devices/"+deviceID+"/attachments/"+attachmentID+"/content", nil)
20		return serveRecorder(h, r)
21	}
22	
23	// The whole-content read over the public HTTP surface: create, push chunks
24	// out of order, seal, then fetch the assembled bytes in one request. The body
25	// is byte-for-byte the per-chunk concatenation, the content type is
26	// application/octet-stream and repeated reads are stable.
27	func TestAttachmentContentEndToEnd(t *testing.T) {
28		h, _ := newTestHandler(t)
29		registerDevice(t, h, "dev-1")
30		registerDevice(t, h, "dev-2")
31		content := []byte("hello world") // 11 bytes, chunks of 4: [hell][o wo][rld]
32		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
33	
34		// Before the seal the read is a 409 JSON error and the upload stays
35		// resumable: chunks are still accepted afterwards.
36		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
37		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
38		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusConflict {
39			t.Fatalf("content before seal = %d, want 409", w.Code)
40		} else {
41			assertJSONError(t, w)
42		}
43		w, body := putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
44		if w.Code != http.StatusOK || body["created"] != true {
45			t.Fatalf("chunk after 409 = %d %v body=%s", w.Code, body, w.Body.String())
46		}
47		w, body = completeAttachment(t, h, "dev-1", "att-1")
48		if w.Code != http.StatusOK || body["complete"] != true {
49			t.Fatalf("complete = %d %v body=%s", w.Code, body, w.Body.String())
50		}
51	
52		// Sealed: the whole content comes back in one read, identical on repeats.
53		assertContent := func(device string) {
54			t.Helper()
55			w := getAttachmentContent(t, h, device, "att-1")
56			if w.Code != http.StatusOK {
57				t.Fatalf("content read = %d body=%s", w.Code, w.Body.String())
58			}
59			if ct := w.Header().Get("Content-Type"); ct != "application/octet-stream" {
60				t.Fatalf("content type = %q, want application/octet-stream", ct)
61			}
62			if w.Body.String() != string(content) {
63				t.Fatalf("content = %q, want %q", w.Body.String(), content)
64			}
65			again := getAttachmentContent(t, h, device, "att-1")
66			if again.Code != http.StatusOK || again.Body.String() != w.Body.String() {
67				t.Fatalf("repeat read = %d %q, want identical bytes", again.Code, again.Body.String())
68			}
69		}
70		assertContent("dev-1")
71	
72		// A granted device reads the same bytes; a stranger gets a 403 that leaks
73		// nothing, and an unknown id a 404.
74		w, _ = postJSON(t, h, "/v1/devices/dev-1/attachments/att-1/access", map[string]any{
75			"deviceId": "dev-2", "action": "grant",
76		})
77		if w.Code != http.StatusOK {
78			t.Fatalf("grant = %d %s", w.Code, w.Body.String())
79		}
80		assertContent("dev-2")
81	
82		registerDevice(t, h, "dev-3")
83		if w := getAttachmentContent(t, h, "dev-3", "att-1"); w.Code != http.StatusForbidden {
84			t.Fatalf("stranger content read = %d, want 403", w.Code)
85		} else {
86			assertJSONError(t, w)
87			if strings.Contains(w.Body.String(), "hello") {
88				t.Fatalf("403 body leaks content: %s", w.Body.String())
89			}
90		}
91		if w := getAttachmentContent(t, h, "dev-1", "nope"); w.Code != http.StatusNotFound {
92			t.Fatalf("unknown content read = %d, want 404", w.Code)
93		} else {
94			assertJSONError(t, w)
95		}
96	
97		// A revoke returns the granted device's read to 403 at once.
98		w, _ = postJSON(t, h, "/v1/devices/dev-1/attachments/att-1/access", map[string]any{
99			"deviceId": "dev-2", "action": "revoke",
100		})
101		if w.Code != http.StatusOK {
102			t.Fatalf("revoke = %d %s", w.Code, w.Body.String())
103		}
104		if w := getAttachmentContent(t, h, "dev-2", "att-1"); w.Code != http.StatusForbidden {
105			t.Fatalf("revoked content read = %d, want 403", w.Code)
106		}
107	}
