109	// A reused (digest-deduplicated) attachment still reads its own assembled
110	// bytes through the whole-content endpoint, identical to the first copy.
111	func TestAttachmentContentReadOnReusedUpload(t *testing.T) {
112		h, _ := newTestHandler(t)
113		registerDevice(t, h, "dev-1")
114		registerDevice(t, h, "dev-2")
115		content := []byte("shared content")
116	
117		for _, tc := range []struct {
118			device, id string
119		}{
120			{"dev-1", "att-1"},
121			{"dev-2", "att-2"},
122		} {
123			mustCreateAttachment(t, h, tc.device, tc.id, content, 8)
124			putChunk(t, h, tc.device, tc.id, 0, content[:8])
125			putChunk(t, h, tc.device, tc.id, 1, content[8:])
126			w, body := completeAttachment(t, h, tc.device, tc.id)
127			if w.Code != http.StatusOK {
128				t.Fatalf("complete %s = %d body=%s", tc.id, w.Code, w.Body.String())
129			}
130			if body["reused"] != (tc.id == "att-2") {
131				t.Fatalf("complete %s reused=%v", tc.id, body["reused"])
132			}
133		}
134	
135		for _, tc := range []struct {
136			device, id string
137		}{
138			{"dev-1", "att-1"},
139			{"dev-2", "att-2"},
140		} {
141			w := getAttachmentContent(t, h, tc.device, tc.id)
142			if w.Code != http.StatusOK || w.Body.String() != string(content) {
143				t.Fatalf("content %s = %d %q", tc.id, w.Code, w.Body.String())
144			}
145		}
146	}
147	
148	// The request-shape matrix of the content endpoint: empty identifiers,
149	// missing or extra segments and non-GET methods are all 400 JSON errors,
150	// judged before any existence or authorization check, and nothing is written.
151	func TestAttachmentContentShapeContract(t *testing.T) {
152		h, _ := newTestHandler(t)
153		registerDevice(t, h, "dev-1")
154		content := []byte("hello world")
155		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
156		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
157		putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
158		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
159		w, body := completeAttachment(t, h, "dev-1", "att-1")
160		if w.Code != http.StatusOK || body["complete"] != true {
161			t.Fatalf("complete = %d %v", w.Code, body)
162		}
163	
164		// Empty identifiers, trailing slashes and extra segments: 400 JSON.
165		for _, path := range []string{
166			"/v1/devices//attachments/att-1/content",
167			"/v1/devices/dev-1/attachments//content",
168			"/v1/devices/dev-1/attachments/att-1/content/",
169			"/v1/devices/dev-1/attachments/att-1/content/extra",
170			"/v1/devices/dev-1/attachments/att-1/content/extra/more",
171		} {
172			r := httptest.NewRequest(http.MethodGet, path, nil)
173			if w := serveRecorder(h, r); w.Code != http.StatusBadRequest {
174				t.Fatalf("GET %s = %d, want 400", path, w.Code)
175			} else {
176				assertJSONError(t, w)
177			}
178		}
179	
180		// Non-GET methods on the exact path and on extra segments: 400 JSON.
181		for _, method := range []string{http.MethodPost, http.MethodPut, http.MethodDelete, http.MethodPatch, http.MethodOptions} {
182			for _, path := range []string{
183				"/v1/devices/dev-1/attachments/att-1/content",
184				"/v1/devices/dev-1/attachments/att-1/content/extra",
185			} {
186				r := httptest.NewRequest(method, path, nil)
187				if w := serveRecorder(h, r); w.Code != http.StatusBadRequest {
188					t.Fatalf("%s %s = %d, want 400", method, path, w.Code)
189				} else {
190					assertJSONError(t, w)
191				}
192			}
193		}
194	
195		// Shape is judged before existence: a non-GET request against an unknown
196		// attachment is still a 400, not a 404.
197		r := httptest.NewRequest(http.MethodDelete, "/v1/devices/dev-1/attachments/nope/content", nil)
198		if w := serveRecorder(h, r); w.Code != http.StatusBadRequest {
199			t.Fatalf("DELETE unknown content = %d, want 400", w.Code)
200		}
201	
202		// The rejections wrote nothing: the content still reads back intact.
203		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusOK || w.Body.String() != string(content) {
204			t.Fatalf("content after rejections = %d %q", w.Code, w.Body.String())
205		}
206	}
207	
208	// The judgment order past the shape checks: existence (404) before
209	// authorization (403) before the seal state (409).
210	func TestAttachmentContentJudgmentOrder(t *testing.T) {
211		h, _ := newTestHandler(t)
212		registerDevice(t, h, "dev-1")
213		registerDevice(t, h, "dev-2")
214		content := []byte("hello world")
215		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
216	
217		// Unsealed upload: a non-creator non-granted device gets 403 (not 409),
218		// the creator gets 409, and an unknown id gets 404 either way.
219		if w := getAttachmentContent(t, h, "dev-2", "att-1"); w.Code != http.StatusForbidden {
220			t.Fatalf("non-creator unsealed = %d, want 403", w.Code)
221		}
222		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusConflict {
223			t.Fatalf("creator unsealed = %d, want 409", w.Code)
224		}
225		if w := getAttachmentContent(t, h, "dev-2", "nope"); w.Code != http.StatusNotFound {
226			t.Fatalf("non-creator unknown = %d, want 404", w.Code)
227		}
228	
229		// A granted device reaches the seal check: 409 like the creator.
230		w, _ := postJSON(t, h, "/v1/devices/dev-1/attachments/att-1/access", map[string]any{
231			"deviceId": "dev-2", "action": "grant",
232		})
233		if w.Code != http.StatusOK {
234			t.Fatalf("grant = %d %s", w.Code, w.Body.String())
235		}
236		if w := getAttachmentContent(t, h, "dev-2", "att-1"); w.Code != http.StatusConflict {
237			t.Fatalf("granted unsealed = %d, want 409", w.Code)
238		} else {
239			assertJSONError(t, w)
240		}
241	
242		// The failed reads left no record: the upload resumes and seals normally.
243		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
244		putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
245		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
246		w, body := completeAttachment(t, h, "dev-1", "att-1")
247		if w.Code != http.StatusOK || body["complete"] != true {
248			t.Fatalf("complete after 409 reads = %d %v", w.Code, body)
249		}
250		if w := getAttachmentContent(t, h, "dev-2", "att-1"); w.Code != http.StatusOK || w.Body.String() != string(content) {
251			t.Fatalf("granted sealed read = %d %q", w.Code, w.Body.String())
252		}
253	}
254	
255	// A deleted attachment's content read is a 404 for everyone, and re-creating
256	// the id starts a brand-new upload whose unsealed read is a 409 again.
257	func TestAttachmentContentAfterDelete(t *testing.T) {
258		h, _ := newTestHandler(t)
259		registerDevice(t, h, "dev-1")
260		content := []byte("hello world")
261		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
262		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
263		putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
264		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
265		w, body := completeAttachment(t, h, "dev-1", "att-1")
266		if w.Code != http.StatusOK || body["complete"] != true {
267			t.Fatalf("complete = %d %v", w.Code, body)
268		}
269		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusOK {
270			t.Fatalf("sealed read = %d", w.Code)
271		}
272	
273		r := httptest.NewRequest(http.MethodDelete, "/v1/devices/dev-1/attachments/att-1", nil)
274		if w := serveRecorder(h, r); w.Code != http.StatusOK {
275			t.Fatalf("delete = %d", w.Code)
276		}
277		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusNotFound {
278			t.Fatalf("content after delete = %d, want 404", w.Code)
279		} else {
280			assertJSONError(t, w)
281		}
282	
283		// The id is free again: a fresh upload under it is unsealed, so the
284		// whole-content read is a 409 until the new upload finishes.
285		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
286		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusConflict {
287			t.Fatalf("recreated unsealed read = %d, want 409", w.Code)
288		}
289	}
290	
291	// The whole-content read and its judgments are durable: after a restart the
292	// sealed bytes read back identically and the 403/404/409 decisions are
293	// unchanged.
294	func TestAttachmentContentSurvivesRestart(t *testing.T) {
295		dbPath := filepath.Join(t.TempDir(), "sync.db")
296		open := func(t *testing.T) (http.Handler, *app.App) {
297			t.Helper()
298			s, err := app.Open(dbPath)
299			if err != nil {
300				t.Fatal(err)
301			}
302			return NewHandler(s), s
303		}
304	
305		h, s := open(t)
306		registerDevice(t, h, "dev-1")
307		registerDevice(t, h, "dev-2")
308		content := []byte("hello world")
309		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
310		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
311		putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
312		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
313		w, body := completeAttachment(t, h, "dev-1", "att-1")
314		if w.Code != http.StatusOK || body["complete"] != true {
315			t.Fatalf("complete = %d %v", w.Code, body)
316		}
317		w, _ = postJSON(t, h, "/v1/devices/dev-1/attachments/att-1/access", map[string]any{
318			"deviceId": "dev-2", "action": "grant",
319		})
320		if w.Code != http.StatusOK {
321			t.Fatalf("grant = %d %s", w.Code, w.Body.String())
322		}
323		// A second upload stays unsealed across the restart.
324		mustCreateAttachment(t, h, "dev-1", "att-2", []byte("data"), 2)
325		_ = s.Close()
326	
327		h, s = open(t)
328		defer func() { _ = s.Close() }()
329	
330		for _, device := range []string{"dev-1", "dev-2"} {
331			w := getAttachmentContent(t, h, device, "att-1")
332			if w.Code != http.StatusOK || w.Body.String() != string(content) ||
333				w.Header().Get("Content-Type") != "application/octet-stream" {
334				t.Fatalf("content after restart (%s) = %d %q %q",
335					device, w.Code, w.Body.String(), w.Header().Get("Content-Type"))
336			}
337		}
338		if w := getAttachmentContent(t, h, "dev-1", "att-2"); w.Code != http.StatusConflict {
339			t.Fatalf("unsealed after restart = %d, want 409", w.Code)
340		}
341		if w := getAttachmentContent(t, h, "dev-1", "nope"); w.Code != http.StatusNotFound {
342			t.Fatalf("unknown after restart = %d, want 404", w.Code)
343		}
344	}
345	
346	// The content read is read-only: it changes neither the metadata view nor the
347	// chunk-level reads, and it coexists with the per-chunk contract — the
348	// assembled body is exactly the per-chunk bytes in ascending index order.
349	func TestAttachmentContentMatchesPerChunkReads(t *testing.T) {
350		h, _ := newTestHandler(t)
351		registerDevice(t, h, "dev-1")
352		content := []byte("the quick brown fox")
353		mustCreateAttachment(t, h, "dev-1", "att-1", content, 3)
354		for i := 0; i*3 < len(content); i++ {
355			lo := i * 3
356			hi := lo + 3
357			if hi > len(content) {
358				hi = len(content)
359			}
360			putChunk(t, h, "dev-1", "att-1", int64(i), content[lo:hi])
361		}
362		w, body := completeAttachment(t, h, "dev-1", "att-1")
363		if w.Code != http.StatusOK || body["complete"] != true {
364			t.Fatalf("complete = %d %v", w.Code, body)
365		}
366	
367		// Assemble the expected body from the per-chunk reads.
368		var want strings.Builder
369		for i := int64(0); i*3 < int64(len(content)); i++ {
370			r := httptest.NewRequest(http.MethodGet,
371				fmt.Sprintf("/v1/devices/dev-1/attachments/att-1/chunks/%d", i), nil)
372			cw := serveRecorder(h, r)
373			if cw.Code != http.StatusOK {
374				t.Fatalf("chunk %d = %d", i, cw.Code)
375			}
376			want.WriteString(cw.Body.String())
377		}
378	
379		w = getAttachmentContent(t, h, "dev-1", "att-1")
380		if w.Code != http.StatusOK || w.Body.String() != want.String() {
381			t.Fatalf("whole content = %d %q, want per-chunk concatenation %q", w.Code, w.Body.String(), want.String())
382		}
383	
384		// The read left no trace: metadata and chunk reads are unchanged.
385		r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1", nil)
386		meta := serveRecorder(h, r)
387		if !strings.Contains(meta.Body.String(), `"complete":true`) ||
388			!strings.Contains(meta.Body.String(), `"receivedChunks":[0,1,2,3,4,5,6]`) {
389			t.Fatalf("meta after content read = %s", meta.Body.String())
390		}
391		r = httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/attachments/att-1/chunks/0", nil)
392		if w := serveRecorder(h, r); w.Code != http.StatusOK || w.Body.String() != "the" {
393			t.Fatalf("chunk 0 after content read = %d %q", w.Code, w.Body.String())
394		}
395	}
