170		// A partial last page and a page past the end.
171		_, page := getAttachmentList(t, h, "/v1/devices/dev-1/attachments?limit=4&offset=4")
172		if got := listIDs(page); !equalStrings(got, []string{"att-5", "att-6"}) {
