13	func TestSetDocumentPermissionLifecycle(t *testing.T) {
14		s, _ := app.Open("")
15		defer func() { _ = s.Close() }()
16	
17		// Unknown device -> store.ErrDeviceNotFound, nothing written.
18		if _, err := s.SetDocumentPermission("doc", "ghost", false); !errors.Is(err, store.ErrDeviceNotFound) {
19			t.Fatalf("unknown device err = %v, want store.ErrDeviceNotFound", err)
20		}
21	
22		if _, err := s.RegisterDevice("dev-1"); err != nil {
23			t.Fatal(err)
24		}
25		if _, err := s.RegisterDevice("dev-2"); err != nil {
26			t.Fatal(err)
27		}
28	
29		// Devices start authorized: no row needed.
30		if ok, err := s.DocumentAuthorized("doc", "dev-1"); err != nil || !ok {
31			t.Fatalf("default authorized = %v err = %v", ok, err)
32		}
33	
34		// Grant on the default state is a no-op.
35		changed, err := s.SetDocumentPermission("doc", "dev-1", true)
36		if err != nil || changed {
37			t.Fatalf("grant on default = changed:%v err:%v", changed, err)
38		}
39	
40		// First revoke flips the state.
41		changed, err = s.SetDocumentPermission("doc", "dev-1", false)
42		if err != nil || !changed {
43			t.Fatalf("first revoke = changed:%v err:%v", changed, err)
44		}
45		if ok, err := s.DocumentAuthorized("doc", "dev-1"); err != nil || ok {
46			t.Fatalf("after revoke authorized = %v err = %v", ok, err)
47		}
48	
49		// Repeating the revoke is idempotent.
50		changed, err = s.SetDocumentPermission("doc", "dev-1", false)
51		if err != nil || changed {
52			t.Fatalf("repeat revoke = changed:%v err:%v", changed, err)
53		}
54	
55		// Permissions are per (document, device): neighbours are untouched.
56		if ok, _ := s.DocumentAuthorized("other-doc", "dev-1"); !ok {
57			t.Fatal("revoke leaked to another document")
58		}
59		if ok, _ := s.DocumentAuthorized("doc", "dev-2"); !ok {
60			t.Fatal("revoke leaked to another device")
61		}
62	
63		// Re-grant flips back; repeating the grant is idempotent again.
64		changed, err = s.SetDocumentPermission("doc", "dev-1", true)
65		if err != nil || !changed {
66			t.Fatalf("re-grant = changed:%v err:%v", changed, err)
67		}
68		changed, err = s.SetDocumentPermission("doc", "dev-1", true)
69		if err != nil || changed {
70			t.Fatalf("repeat grant = changed:%v err:%v", changed, err)
71		}
72		if ok, _ := s.DocumentAuthorized("doc", "dev-1"); !ok {
73			t.Fatal("device should be authorized after re-grant")
74		}
75	}
