115	func TestConcurrentSetDocumentPermission(t *testing.T) {
116		s, _ := app.Open("")
117		defer func() { _ = s.Close() }()
118		if _, err := s.RegisterDevice("dev"); err != nil {
119			t.Fatal(err)
120		}
121	
122		// Concurrent identical revokes: exactly one reports a change.
123		const n = 40
124		var wg sync.WaitGroup
125		var mu sync.Mutex
126		changedCount := 0
127		errCh := make(chan error, n+2)
128		for i := 0; i < n; i++ {
129			wg.Add(1)
130			go func() {
131				defer wg.Done()
132				changed, err := s.SetDocumentPermission("doc", "dev", false)
133				if err != nil {
134					errCh <- err
135					return
136				}
137				if changed {
138					mu.Lock()
139					changedCount++
140					mu.Unlock()
141				}
142			}()
