// ListDevicesTx returns the ids of every currently registered device in
// ascending lexicographic order, evaluated inside q so a read sharing another
// service's transaction sees one consistent registration snapshot. Deregistered
// devices are absent.
func ListDevicesTx(q DBTX) ([]string, error) {
	rows, err := q.Query(`SELECT id FROM devices ORDER BY id ASC`)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()
	devices := make([]string, 0)
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		devices = append(devices, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return devices, nil
}

